\begin{ex}%[6H4N2]
\immini[thm]{
Nêu tên đỉnh, cạnh, đường chéo, hai cạnh đối của hình bình hành  ${A B C D }$
}{
\begin{tikzpicture}

    % Định nghĩa các đỉnh của hình bình hành
    \coordinate [label=above left:{$A $}] (A) at (0, 0);
    \coordinate [label=above right:{$B $}] (B) at (4, 0);
    \coordinate [label=below right:{$C $}] (C) at (5, -3);
    \coordinate [label=below left:{$D $}] (D) at (1, -3);

    % Vẽ các cạnh của hình bình hành
    \draw[thick] (A) -- (B) -- (C) -- (D) -- cycle;

    % Vẽ các điểm
    \fill (A) circle (2pt);
    \fill (B) circle (2pt);
    \fill (C) circle (2pt);
    \fill (D) circle (2pt);

\end{tikzpicture}
}
\loigiai{
Đỉnh ${A ,B ,C ,D }$\\
Cạnh ${A B }$, ${B C }$, ${C D }$, ${A D }$\\
Đường chéo ${A C }$, ${B D }$\\
Hai cạnh đối là ${A B }$, ${C D }$ và ${C B }$, ${A D }$
}\end{ex}

